// 금융위원회 보도자료 목록 페이지에서 당일 등록 건 추출
const html = $input.first().json.data;
const today = new Date();
const year = today.getFullYear();
const month = String(today.getMonth() + 1).padStart(2, '0');
const day = String(today.getDate()).padStart(2, '0');
const todayStr = `${year}.${month}.${day}`;
const todayStrAlt = `${year}-${month}-${day}`;

// 보도자료 목록에서 당일 날짜의 항목 추출
// FSC 페이지는 일반적으로 테이블 형태로 목록이 표시됨
const items = [];

// 정규식으로 목록 항목 파싱 (제목, 날짜, 링크)
// FSC 사이트 구조: /no010101/view?noticeId=XXXX 형태
const linkPattern = /\/no010101\/view\?noticeId=(\d+)/g;
const titlePattern = /<td[^>]*class="[^"]*subject[^"]*"[^>]*>.*?<a[^>]*href="[^"]*noticeId=(\d+)"[^>]*>(.*?)<\/a>/gs;
const datePattern = new RegExp(`(${todayStr}|${todayStrAlt})`, 'g');

// 테이블 행 단위로 파싱
const rowPattern = /<tr[^>]*>(.*?)<\/tr>/gs;
let match;
while ((match = rowPattern.exec(html)) !== null) {
  const row = match[1];
  // 날짜가 오늘인 행만 필터링
  if (row.includes(todayStr) || row.includes(todayStrAlt)) {
    // noticeId 추출
    const idMatch = /noticeId=(\d+)/.exec(row);
    // 제목 추출
    const titleMatch = /<a[^>]*>(.*?)<\/a>/s.exec(row);
    if (idMatch && titleMatch) {
      items.push({
        json: {
          noticeId: idMatch[1],
          title: titleMatch[1].replace(/<[^>]*>/g, '').trim(),
          date: todayStr,
          url: `https://www.fsc.go.kr/no010101/view?noticeId=${idMatch[1]}`,
          source: '금융위원회'
        }
      });
    }
  }
}

if (items.length === 0) {
  return [{ json: { noData: true, message: '오늘 등록된 보도자료가 없습니다.' } }];
}

return items;

// 상세 페이지에서 첨부파일 중 PDF 파일 URL 추출
const html = $input.first().json.data;
const noticeId = $input.first().json.noticeId || '';
const title = $input.first().json.title || '';

// 첨부파일 영역에서 PDF 링크 추출
// FSC 사이트의 첨부파일 패턴
const pdfLinks = [];

// 일반적인 첨부파일 다운로드 패턴
const attachPattern = /href="([^"]*\.pdf[^"]*)"/gi;
let match;
while ((match = attachPattern.exec(html)) !== null) {
  let pdfUrl = match[1];
  if (!pdfUrl.startsWith('http')) {
    pdfUrl = 'https://www.fsc.go.kr' + pdfUrl;
  }
  pdfLinks.push(pdfUrl);
}

// 파일 다운로드 링크 패턴 (atchFileId 등)
const atchPattern = /\/cmm\/fms\/FileDown\.do\?[^"']*/gi;
while ((match = atchPattern.exec(html)) !== null) {
  let fileUrl = 'https://www.fsc.go.kr' + match[0];
  pdfLinks.push(fileUrl);
}

// 본문 내용 추출 (정책 요약용)
const contentMatch = /<div[^>]*class="[^"]*view[_-]?con(tent)?[^"]*"[^>]*>(.*?)<\/div>/s.exec(html);
const content = contentMatch ? contentMatch[2].replace(/<[^>]*>/g, '').trim().substring(0, 500) : '';

return [{
  json: {
    noticeId,
    title,
    content,
    pdfUrls: pdfLinks,
    pdfCount: pdfLinks.length,
    date: new Date().toISOString().split('T')[0]
  }
}];

// PDF URL을 개별 항목으로 분리
const item = $input.first().json;
const results = [];

if (item.pdfUrls && item.pdfUrls.length > 0) {
  for (let i = 0; i < item.pdfUrls.length; i++) {
    results.push({
      json: {
        noticeId: item.noticeId,
        title: item.title,
        content: item.content,
        pdfUrl: item.pdfUrls[i],
        pdfIndex: i + 1,
        date: item.date
      }
    });
  }
} else {
  results.push({
    json: {
      noticeId: item.noticeId,
      title: item.title,
      content: item.content,
      pdfUrl: null,
      pdfIndex: 0,
      date: item.date
    }
  });
}

return results;

// 정부정책 발송 메시지 포맷팅
const items = $input.all();
const policyMessages = [];

for (const item of items) {
  const d = item.json;
  policyMessages.push({
    title: d.title,
    content: d.content,
    url: `https://www.fsc.go.kr/no010101/view?noticeId=${d.noticeId}`,
    date: d.date,
    source: '금융위원회'
  });
}

return [{
  json: {
    type: 'government_policy',
    policies: policyMessages,
    count: policyMessages.length
  }
}];
